local function lookup(r,cp,default) local lo,hi=1,#r while lo<=hi do local m=math.floor((lo+hi)/2);local x=r[m] if cp<x[1] then hi=m-1 elseif cp>x[2] then lo=m+1 else return x[3] end end return default end
function P.grapheme(cp) return lookup(gcb,tonumber(cp) or -1,"Other") end
function P.incb(cp) return lookup(incb,tonumber(cp) or -1,"None") end
function P.extended_pictographic(cp) return lookup(ep,tonumber(cp) or -1,false)==true end
return P
